('Enabled', 'af', 'Geaktiveer'),
('Enabling a feature never grants a role anything the route matrix and row-level security would not — the two systems compose. Disabling one hides it everywhere and makes its server routes refuse, for this tenant only.', 'af', 'Om ''n funksie te aktiveer, gee nooit ''n rol iets wat die roetematriks en ryvlak-sekuriteit nie sou toelaat nie — die twee stelsels werk saam. Om een te deaktiveer, versteek dit oral en laat sy bedienerroetes weier, net vir hierdie huurder.'),
