('Official insignia belong to the municipality and its services, so the platform ships none — upload each department''s real crest here and it appears everywhere immediately. Until then a monogram badge renders in that department''s colours, so nothing ever looks unfinished. PNG or SVG with a transparent background works best; square crops read cleanest at small sizes.', 'af', 'Amptelike kentekens behoort aan die munisipaliteit en sy dienste, so die platform lewer geen nie — laai elke departement se regte wapen hier op en dit verskyn dadelik oral. Tot dan word ''n monogramkenteken in daardie departement se kleure gewys, sodat niks ooit onvoltooid lyk nie. PNG of SVG met ''n deursigtige agtergrond werk die beste; vierkantige uitsnitte lees die skoonste op klein groottes.'),
