('To be completed by police member', 'af', 'Deur polisielid te voltooi'),
('To capture leave or absence for a member, fill in the form.', 'af', 'Om verlof of afwesigheid vir ''n lid aan te teken, vul die vorm in.'),
('To change a duty, press Edit on its row in All duty records.', 'af', 'Om ''n diens te verander, druk Wysig op sy ry in Alle diensrekords.'),
